<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfilePhoneNumberAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfilePhoneNumberAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfilePhoneNumberAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPhoneNumber returns null on a freshly created holder.
     */
    public function testPhoneNumberNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePhoneNumberAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPhoneNumberAssigned());
        $this->assertNull($holder->getPhoneNumber());
    }
}
class ImplWithUserProfilePhoneNumberAttributeHolderUnitTest
{
    use UserProfilePhoneNumberAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPhoneNumberRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPhoneNumber();
    }
}
